effects.css:
background: linear-gradient(135deg, rgba(255, 255, 255, 0.06) 0%, rgba(255, 255, 255, 0.02) 100%);
border: 1px solid rgba(255, 255, 255, 0.1);
backdrop-filter: blur(24px) saturate(180%);
-webkit-backdrop-filter: blur(24px) saturate(180%);
box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.1), 0 24px 48px -16px rgba(0, 0, 0, 0.5);
border-radius: 20px;

background: linear-gradient(135deg, rgba(255, 45, 111, 0.1) 0%, rgba(255, 45, 111, 0.02) 100%);
border: 1px solid rgba(255, 45, 111, 0.18);
backdrop-filter: blur(28px) saturate(180%);
-webkit-backdrop-filter: blur(28px) saturate(180%);
box-shadow: inset 0 1px 0 rgba(255, 45, 111, 0.2), 0 24px 48px -16px rgba(124, 45, 90, 0.5);
border-radius: 20px;

position: relative;
border-radius: 22px;
background: linear-gradient(135deg, rgba(255, 255, 255, 0.05) 0%, rgba(255, 255, 255, 0.01) 100%);
border: 1px solid rgba(255, 255, 255, 0.08);
backdrop-filter: blur(24px) saturate(180%);
box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.06), 0 16px 36px -12px rgba(0, 0, 0, 0.4);
transition: all 0.5s cubic-bezier(0.4, 0, 0.2, 1);
overflow: hidden;

content: '';
position: absolute;
inset: 0;
pointer-events: none;
opacity: 0;
background: radial-gradient(ellipse 80% 70% at 50% 0%, rgba(255, 45, 111, 0.18) 0%, transparent 70%);
transition: opacity 0.5s;

content: "";
position: absolute;
inset: 0;
z-index: 2;
border-radius: inherit;
padding: 2px;
background: conic-gradient( from var(--shimmer-angle), #FFE3B0, #FF2D6F, #FF5E3A, #FFD24A, #FF2D6F, #FFE3B0 );
-webkit-mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
-webkit-mask-composite: xor;
mask-composite: exclude;
pointer-events: none;
animation: shimmer-spin 3s linear infinite;

display: inline-flex;
align-items: center;
gap: 8px;
padding: 8px 14px;
border-radius: 999px;
background: rgba(255, 184, 55, 0.10);
border: 1px solid rgba(255, 184, 55, 0.30);
backdrop-filter: blur(12px);
font-size: 12px;
font-weight: 700;
letter-spacing: 0.14em;
text-transform: uppercase;
color: #FFD24A;

width: 6px;
height: 6px;
border-radius: 50%;
background: #FFD24A;
box-shadow: 0 0 8px #FFD24A;
animation: pulse-ds 2s ease-in-out infinite;

display: inline-flex;
align-items: center;
gap: 10px;
padding: 16px 28px;
border-radius: 12px;
background: linear-gradient(135deg, var(--emerald) 0%, var(--emerald-deep) 100%);
color: var(--bg-0);
font-weight: 800;
font-size: 15px;
letter-spacing: 0.01em;
text-decoration: none;
border: none;
cursor: pointer;
box-shadow: 0 12px 36px -8px rgba(255, 45, 111, 0.55), inset 0 1px 0 rgba(255, 255, 255, 0.3);
transition: all 0.3s;
font-family: inherit;

display: inline-flex;
align-items: center;
gap: 10px;
padding: 15px 26px;
border-radius: 12px;
background: rgba(255, 255, 255, 0.05);
border: 1px solid rgba(255, 255, 255, 0.12);
backdrop-filter: blur(20px);
color: var(--ink);
font-weight: 700;
font-size: 14px;
text-decoration: none;
cursor: pointer;
transition: all 0.3s;
font-family: inherit;

display: inline-block;
background: linear-gradient(135deg, var(--emerald) 0%, var(--teal) 60%, var(--emerald) 100%);
background-size: 200% 200%;
-webkit-background-clip: text;
background-clip: text;
-webkit-text-fill-color: transparent;
animation: gradientShift 6s ease-in-out infinite;
font-style: italic;
padding: 0.12em 0.18em 0.18em 0;
margin: -0.12em -0.04em -0.18em 0;
line-height: 1.18;
vertical-align: baseline;

position: fixed;
inset: 0;
z-index: 1;
background-image: linear-gradient(to right, rgba(255, 45, 111, 0.05) 1px, transparent 1px), linear-gradient(to bottom, rgba(255, 45, 111, 0.05) 1px, transparent 1px);
background-size: 56px 56px;
mask-image: radial-gradient(ellipse 100% 70% at 50% 50%, black 30%, transparent 80%);
pointer-events: none;

position: fixed;
z-index: 1;
border-radius: 50%;
filter: blur(64px);
pointer-events: none;
transform: translateZ(0);

position: fixed;
inset: 0;
z-index: 1;
pointer-events: none;
opacity: 0.04;
background-image: url("/images/noise.png");
background-size: 128px 128px;
background-repeat: repeat;
transform: translateZ(0);

opacity: 0;
transform: translateY(40px);
transition: opacity 0.9s ease-out, transform 0.9s cubic-bezier(0.4, 0, 0.2, 1);

keyframes.css:
@keyframes fadeIn {
  0% {
    opacity: 0;
    transform: translateY(10px);
  }
  100% {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes orbA {
  0%, 100% { transform: translate(0, 0) scale(1); }
  50% { transform: translate(-80px, 60px) scale(1.1); }
}

@keyframes orbB {
  0%, 100% { transform: translate(0, 0) scale(1); }
  50% { transform: translate(80px, -40px) scale(1.15); }
}

@keyframes orbC {
  0%, 100% { transform: translate(0, 0) scale(1); }
  50% { transform: translate(60px, 80px) scale(0.85); }
}
